    return Opcode::JUN;
  case 0b0101:
    return Opcode::JMS;
  case 0b0110:
    return Opcode::INC;
  case 0b0111:
    return Opcode::ISZ;
  case 0b1000:
    return Opcode::ADD;
  case 0b1001:
    return Opcode::SUB;
  case 0b1010:
    return Opcode::LD;
  case 0b1011:
    return Opcode::XCH;
  case 0b1100:
    return Opcode::BBL;
  case 0b1101:
    return Opcode::LDM;
  case 0b1110:
