    case 0b1001:
      return Opcode::RDM;
    case 0b1010:
      return Opcode::RDR;
    case 0b1011:
      return Opcode::ADM;
    case 0b1100:
      return Opcode::RD0;
    case 0b1101:
      return Opcode::RD1;
    case 0b1110:
      return Opcode::RD2;
    case 0b1111:
      return Opcode::RD3;
    }
  case 0b1111:
